#!/usr/bin/env python3
"""AUDIT A7 -- INDEPENDENT core engine for the N=8 template model.

Written from the model definition only (no import from W8/W12/W15/W16/W19/W20).
Deliberately different implementation routes from the probe engines:
  * perfect matchings generated by a bitmask recursion over *sorted pair sets*
    and independently cross-checked by a permutation-based generator;
  * H_w evaluated both by direct matching enumeration AND by a subset-DP
    (hafnian recursion) -- the two must agree;
  * all arithmetic exact (int / Fraction / sympy Rational).

MODEL (restated).  N = 8 sites, each C^3.  One 3x3 block A_uv per edge u<v of
K_8; row index = colour at u, column index = colour at v.  For w in {0,1,2}^8

    H_w(A) = sum over perfect matchings M of K_8 of prod_{uv in M} A_uv[w_u][w_v]

An EXACT SOURCE with template T: every cell occupied by T is nonzero, every
other cell is zero, H_w = 0 on all 6558 mixed words and H_w != 0 on the three
constant words.

TEMPLATE ENCODING (as in the probe corpus, re-derived here): T[e] is a 9-bit
mask, bit 3*i+j set iff cell (i,j) of block e is occupied; e indexes
combinations(range(8),2) lexicographically.
"""
from __future__ import annotations

from fractions import Fraction
from itertools import combinations, product, permutations

N = 8
Q = 3
FULL = (1 << 9) - 1

EDGES = tuple(combinations(range(N), 2))
EIDX = {e: i for i, e in enumerate(EDGES)}


# ------------------------------------------------------- perfect matchings
def _pm_bitmask(n=N):
    """Recursion over bitmasks: repeatedly match the LOWEST free vertex."""
    full = (1 << n) - 1
    out = []

    def rec(used, acc):
        if used == full:
            out.append(tuple(sorted(acc)))
            return
        a = 0
        while (used >> a) & 1:
            a += 1
        for b in range(a + 1, n):
            if not (used >> b) & 1:
                rec(used | (1 << a) | (1 << b), acc + [(a, b)])

    rec(0, [])
    return sorted(out)


def _pm_perm(n=N):
    """Totally different route: canonicalise every permutation of 0..n-1."""
    seen = set()
    for p in permutations(range(n)):
        m = tuple(sorted(tuple(sorted((p[2 * i], p[2 * i + 1])))
                         for i in range(n // 2)))
        seen.add(m)
    return sorted(seen)


PMS = tuple(_pm_bitmask())
assert len(PMS) == 105, len(PMS)
PM_E = tuple(tuple(EIDX[e] for e in m) for m in PMS)

WORDS = tuple(product(range(Q), repeat=N))
CONSTS = tuple(tuple([c] * N) for c in range(Q))
MIXED = tuple(w for w in WORDS if len(set(w)) > 1)


def cell_index(ei, w):
    u, v = EDGES[ei]
    return 3 * w[u] + w[v]


def occupied(T, ei, w):
    return (T[ei] >> cell_index(ei, w)) & 1


def fibre(T, w):
    """indices of perfect matchings fully occupied at word w."""
    return [mi for mi, es in enumerate(PM_E)
            if all((T[e] >> cell_index(e, w)) & 1 for e in es)]


def fibre_dp(T, w, n=N):
    """Independent route: count the fibre by subset DP (hafnian recursion)."""
    full = (1 << n) - 1
    memo = {}

    def rec(used):
        if used == full:
            return 1
        if used in memo:
            return memo[used]
        a = 0
        while (used >> a) & 1:
            a += 1
        tot = 0
        for b in range(a + 1, n):
            if (used >> b) & 1:
                continue
            e = EIDX[(a, b)]
            if (T[e] >> cell_index(e, w)) & 1:
                tot += rec(used | (1 << a) | (1 << b))
        memo[used] = tot
        return tot

    return rec(0)


def H_value(T, w, A):
    """H_w for an explicit assignment A: dict (edge_index, cell) -> value.
    Direct enumeration over the fibre."""
    tot = 0
    for mi in fibre(T, w):
        p = 1
        for e in PM_E[mi]:
            p *= A[(e, cell_index(e, w))]
        tot += p
    return tot


def H_value_dp(T, w, A, n=N):
    """Independent route: subset DP."""
    full = (1 << n) - 1
    memo = {}

    def rec(used):
        if used == full:
            return 1
        if used in memo:
            return memo[used]
        a = 0
        while (used >> a) & 1:
            a += 1
        tot = 0
        for b in range(a + 1, n):
            if (used >> b) & 1:
                continue
            e = EIDX[(a, b)]
            c = cell_index(e, w)
            if (T[e] >> c) & 1:
                tot += A[(e, c)] * rec(used | (1 << a) | (1 << b))
        memo[used] = tot
        return tot

    return rec(0)


# ------------------------------------------------------------------ Gamma
def gamma_edge_indices(T):
    return [i for i, t in enumerate(T) if t == FULL]


def gamma_edges(T):
    return [EDGES[i] for i in gamma_edge_indices(T)]


def F_gamma(T):
    """perfect matchings entirely inside Gamma (supported at EVERY word)."""
    G = set(gamma_edge_indices(T))
    return [mi for mi, es in enumerate(PM_E) if all(e in G for e in es)]


def extras(T, w, Fg=None):
    if Fg is None:
        Fg = F_gamma(T)
    S = set(Fg)
    return [mi for mi in fibre(T, w) if mi not in S]


def k_of(T, w, Fg=None):
    return len(extras(T, w, Fg))


def effectively_clean(T, w, Fg=None):
    return not extras(T, w, Fg)


def single_cells(T):
    """edge index -> ((u, colour_u), (v, colour_v)) for 1-cell blocks."""
    o = {}
    for e, t in enumerate(T):
        if t and bin(t).count("1") == 1:
            c = t.bit_length() - 1
            u, v = EDGES[e]
            o[e] = ((u, c // 3), (v, c % 3))
    return o


def word_clean(T, w, sc=None):
    if sc is None:
        sc = single_cells(T)
    for e, ((u, cu), (v, cv)) in sc.items():
        if w[u] == cu and w[v] == cv:
            return False
    return True


def template_stats(T):
    m = sum(1 for t in T if t)
    sigma = sum(bin(t).count("1") for t in T)
    Fg = F_gamma(T)
    hist = {}
    kh = {}
    for w in MIXED:
        s = len(fibre(T, w))
        hist[s] = hist.get(s, 0) + 1
        kk = k_of(T, w, Fg)
        kh[kk] = kh.get(kk, 0) + 1
    return dict(m=m, sigma=sigma, fibre_hist=hist, k_hist=kh,
                min_mixed_fibre=min(hist), n_gamma=len(gamma_edge_indices(T)),
                gamma=gamma_edges(T), nF=len(Fg),
                consts=[len(fibre(T, w)) for w in CONSTS],
                n_eff_clean=sum(1 for w in MIXED if k_of(T, w, Fg) == 0),
                n_word_clean=sum(1 for w in MIXED if word_clean(T, w)))


# ---- W8 immunity templates, transcribed for reproduction (independently
# ---- re-derived checks in a7_templates.py against the W8 stored JSON).
W8_IMMUNE = {
    20: [511, 0, 511, 1, 2, 4, 0, 511, 0, 0, 8, 16, 4, 511, 8, 0, 128, 32,
         64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    21: [511, 511, 511, 1, 2, 4, 0, 511, 0, 0, 8, 16, 4, 511, 8, 0, 128, 32,
         64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    22: [511, 511, 511, 1, 2, 4, 511, 511, 0, 0, 8, 16, 4, 511, 8, 0, 128,
         32, 64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    23: [511, 511, 511, 1, 2, 4, 511, 511, 511, 0, 8, 16, 4, 511, 8, 0, 128,
         32, 64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    24: [511, 511, 511, 1, 2, 4, 511, 511, 511, 511, 8, 16, 4, 511, 8, 0,
         128, 32, 64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    25: [511, 511, 511, 1, 2, 4, 511, 511, 511, 511, 8, 16, 4, 511, 8, 511,
         128, 32, 64, 128, 0, 256, 511, 0, 511, 511, 0, 511],
    26: [511, 511, 511, 1, 2, 4, 511, 511, 511, 511, 8, 16, 4, 511, 8, 511,
         128, 32, 64, 128, 511, 256, 511, 0, 511, 511, 0, 511],
    27: [511, 511, 511, 1, 2, 4, 511, 511, 511, 511, 8, 16, 4, 511, 8, 511,
         128, 32, 64, 128, 511, 256, 511, 511, 511, 511, 0, 511],
    28: [511, 511, 511, 1, 2, 4, 511, 511, 511, 511, 8, 16, 4, 511, 8, 511,
         128, 32, 64, 128, 511, 256, 511, 511, 511, 511, 511, 511],
}


if __name__ == "__main__":
    # self-tests
    assert _pm_bitmask() == _pm_perm(), "PM generators disagree"
    print("PM generators agree:", len(PMS), "perfect matchings")
    T = W8_IMMUNE[25]
    import random
    rnd = random.Random(20260815)
    bad = 0
    for _ in range(400):
        w = tuple(rnd.randrange(3) for _ in range(N))
        if len(fibre(T, w)) != fibre_dp(T, w):
            bad += 1
    print("fibre vs DP mismatches on 400 random words:", bad)
    A = {}
    for e in range(28):
        for c in range(9):
            if (T[e] >> c) & 1:
                A[(e, c)] = Fraction(rnd.randrange(-9, 10) or 3,
                                     rnd.randrange(1, 5))
    bad = 0
    for _ in range(60):
        w = tuple(rnd.randrange(3) for _ in range(N))
        if H_value(T, w, A) != H_value_dp(T, w, A):
            bad += 1
    print("H direct vs DP mismatches on 60 random words:", bad)
